"""Owner sign-in and revocation UI; credentials stay out of browser storage."""

AUTH_HTML = r'''<!doctype html><html lang="en" data-spoke="false" data-owner="false"><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>BURNRATE · Owner access</title>
<style>
:root{color-scheme:light dark;font-family:"Segoe UI Variable Text","Segoe UI",system-ui,sans-serif;color:#141311;background:#ebe9e4}
*{box-sizing:border-box}body{margin:0;padding:24px}main{max-width:720px;margin:auto;display:grid;gap:20px}section,details{background:#f8f7f4;border:1px solid rgba(20,18,15,.12);border-radius:12px;padding:20px}h1,h2,p{margin:0}h1{font-size:28px}h2{font-size:20px}form,label,section{display:grid;gap:12px}input,button{font:inherit;padding:10px;border:1px solid #74706a;border-radius:6px}button{cursor:pointer;background:#cf4509;color:white}a{color:#a53808}small{color:#4a4741}#status{white-space:pre-wrap;overflow-wrap:anywhere}.session{padding:12px 0;border-bottom:1px solid #74706a;display:flex;flex-wrap:wrap;gap:12px;align-items:center}.session span{flex:1;min-width:160px}.actions{display:flex;gap:12px;flex-wrap:wrap}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere}
@media(prefers-color-scheme:dark){:root{color:#f5f2ed;background:#171614}section,details{background:#22211e;border-color:#74706a}a{color:#ff9b6a}small{color:#d4cec4}input{background:#171614;color:#f5f2ed}}
</style><main><a href="/">Back to usage</a><h1>Owner access</h1>
<p id="scope">Sign in to see All computers and manage your hub.</p>
<section><h2>Sign in</h2><form id="login"><label>Username<input id="username" autocomplete="username" required maxlength="64"></label><label>Password<input id="password" type="password" autocomplete="current-password" required></label><label>Device label<input id="device" value="Browser" maxlength="80"></label><button>Sign in</button></form><small>Sessions expire after 30 days. Machine sync remains separate.</small></section>
<p id="status" role="status" aria-live="polite"></p>
<details id="first-owner" hidden><summary>Create the first owner account</summary><form id="register"><label>Username<input id="new-user" autocomplete="username" required maxlength="64"></label><label>Password (at least 12 characters)<input id="new-password" type="password" autocomplete="new-password" minlength="12" required></label><label>First-account setup token<input id="setup-token" type="password" autocomplete="off"></label><button>Create owner account</button></form><small>On an existing hub, use Sign in above. The setup token is only for the first account.</small></details>
<section><h2>Sessions</h2><div class="actions"><button id="refresh">Refresh sessions</button><button id="logout">Sign out this device</button><button id="renew">Rotate this session</button></div><div id="sessions"></div></section>
<section><h2>Machine credential</h2><p>On a paired computer, refresh its 90-day sync token before expiry. An expired or revoked computer needs a fresh pairing code.</p><button id="machine">Rotate this computer's token</button></section>
<details><summary>Recovery and automation</summary><form id="bootstrap"><label>Break-glass credential<input id="recovery" type="password" autocomplete="off" required></label><button>Create recovery session</button></form><p>Rotate the recovery credential if exposed. Save the replacement in your password manager.</p><button id="rotate">Rotate break-glass credential</button><pre id="replacement"></pre></details>
<script>
let spoke=document.documentElement.dataset.spoke==='true';const el=id=>document.getElementById(id);const status=text=>el('status').textContent=text;
async function api(path,body,bearer){const headers={'Content-Type':'application/json','X-BURNRATE-Request':'1'};if(bearer)headers.Authorization='Bearer '+bearer;const res=await fetch(path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(data.error||'Request failed. Sign in again.');return data;}
async function run(fn){try{await fn();}catch(e){status(e.message);}}
async function sessions(){const data=await api('/api/auth/sessions');el('sessions').replaceChildren();for(const s of data.sessions){const row=document.createElement('div');row.className='session';const name=document.createElement('span');name.textContent=s.device_label+' · '+(s.revoked_at?'revoked':'expires '+s.expires_at)+(s.id===data.currentSessionId?' · this device':'');row.append(name);if(!s.revoked_at){const b=document.createElement('button');b.textContent='Revoke';b.onclick=()=>run(async()=>{await api('/api/auth/sessions/revoke',{id:s.id});status('Session revoked.');await sessions();});row.append(b);}el('sessions').append(row);}}
function context(data){spoke=data.spoke;el('first-owner').hidden=spoke||data.hasOwner;if(spoke)el('scope').textContent='Showing this computer until you sign in. Your owner session unlocks All computers and can be revoked from the hub.';}
context({spoke,hasOwner:document.documentElement.dataset.owner==='true'});
run(async()=>context(await api('/api/auth/context')));
el('login').onsubmit=e=>{e.preventDefault();run(async()=>{try{await api(spoke?'/api/setup/owner-session':'/api/account/login',{username:el('username').value,password:el('password').value,deviceLabel:el('device').value,sessionOnly:true});status('Signed in. All computers is available.');await sessions();}finally{el('password').value='';}});};
el('register').onsubmit=e=>{e.preventDefault();if(spoke){status('Create the owner account on your hub.');return;}run(async()=>{try{await api('/api/account/register',{username:el('new-user').value,password:el('new-password').value,setupToken:el('setup-token').value,deviceLabel:el('device').value,sessionOnly:true});status('Owner account created.');await sessions();}finally{el('new-password').value='';el('setup-token').value='';}});};
el('refresh').onclick=()=>run(sessions);el('logout').onclick=()=>run(async()=>{await api('/api/auth/logout',{});el('sessions').replaceChildren();status('Signed out. A paired computer now shows its own usage.');});
el('renew').onclick=()=>run(async()=>{await api('/api/auth/session/rotate',{});status('Session rotated.');await sessions();});
el('machine').onclick=()=>run(async()=>{await api('/api/setup/rotate-machine',{});status('Machine token rotated; sync uses the replacement.');});
el('bootstrap').onsubmit=e=>{e.preventDefault();run(async()=>{try{await api('/api/auth/bootstrap',{},el('recovery').value);status('Recovery session created.');await sessions();}finally{el('recovery').value='';}});};
el('rotate').onclick=()=>run(async()=>{const data=await api('/api/auth/rotate',{});el('replacement').textContent=data.token;status(data.warning);});
</script></main></html>'''
